import{_ as s,l,o as e,c as d,v as r,p as i,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"地址空间布局","description":"","frontmatter":{"title":"地址空间布局","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/addrspace-layout.md","filePath":"cs/addrspace-layout.md","lastUpdated":1789023840000}'),h={name:"cs/addrspace-layout.md"};function m(E,a,A,_,u,B){const o=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="地址空间布局" tabindex="-1">地址空间布局 <a class="header-anchor" href="#地址空间布局" aria-label="Permalink to &quot;地址空间布局&quot;">​</a></h1><div class="epigraph"><p>每个进程看见一段自己的虚地址：代码、数据、堆向高处长，栈向低处长；内核通常另有映射。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Silberschatz et al. 整理</footer></div><p><a href="/cs/lock-ordering">上一课</a>把同步与死锁回避收束。<a href="/cs/process-image">进程映像</a>只说「有一份地址空间」，还没有画出用户虚地址里各段放哪。<a href="/cs/paging-vm">分页</a>已能把任意虚页接到物理页，本课不重导页表，只规定<strong>布局惯例</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加载器把代码放进内存后，堆从哪长、栈从哪长、共享库映射到哪，若没有约定，编译器生成的绝对地址与 <code>brk</code>/<code>mmap</code> 会对撞。缺口不是 TLB 怎么填，而是用户空间的分区：只读文本、已初始化数据、BSS、堆、栈、以及稍后的内存映射区。内核空间是否映射进每个进程，是同一张图的上半或另半，本课点名即可。</p><p>本课不把 ASLR 的随机化分布写成安全课。</p><p><span class="marginnote">经典 Unix：低地址文本，之上数据与堆，高用户地址栈。Linux 用户/内核分界随架构而变；对象仍是「一段用户可用虚区间」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链接器给出段的虚地址；内核为进程建页表，把合法区间标成可读/写/执行。<a href="/cs/load-dynlink">加载</a>已谈重定位；本课只要求：堆通过 <code>brk</code> 或匿名映射向高地址扩展，栈在故障时可向下扩一页（直到资源上限）。空洞（未映射）访问走缺页异常，下一课才说是立刻分配还是拒绝。</p>',9)),(e(),i(p,null,{default:t(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TEXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%20BSS%22%5D%0A%20%20DATA%20--%3E%20HEAP%5B%22%E5%A0%86%E5%90%91%E4%B8%8A%22%5D%0A%20%20STACK%5B%22%E6%A0%88%E5%90%91%E4%B8%8B%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E5%8C%BA%3A%20%E5%90%8E%E8%AF%BE%20mmap%22%5D%0A%20%20HEAP%20--%3E%20HOLE%5B%22%E6%9C%AA%E6%98%A0%E5%B0%84%E7%A9%BA%E6%B4%9E%22%5D%0A%20%20STACK%20--%3E%20HOLE%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>布局把「映像」变成可检查的区间集合：栈溢出是碰到守卫页或碰到堆，而不是神秘写坏内核——用户写不进内核页，靠的是分页权限，不是本课新硬件。线程各有栈，仍落在同一布局的不同区间，与<a href="/cs/thread-shared-addr">共享地址空间</a>一致。</p><p>内核映射若出现在每个进程的高半，系统调用路径上内核才能用自己的指针；用户仍不可执行那些页上的内核代码当用户指令。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 32 位 3G/1G 与 64 位 canonical 地址的全部数字，不把 vsyscall 页写进主干。也不把文件映射的空洞策略提前：那是 mmap 课。安全栏的 NX 与 ASLR 用本课的段权限当前提，本课不讲攻击。</p><p>共享库的 PIC 文本可被多进程映射到不同虚地址；物理帧仍可共享，这是后课 mmap 的伏笔。</p><p>后课默认：用户虚空间有文本、数据、堆、栈和空洞。空洞何时因访问而变成有效页，下一课按需调页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进程映像的虚地址按段布局；堆与栈相对生长。</li><li>页表权限执行布局；本课不重导页表。</li><li>未映射页的补页策略是按需调页的缺口。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const S=s(h,[["render",m]]);export{T as __pageData,S as default};
